    // ------- 交互逻辑保留原样，仅微改变量名避免冲突 -------
    document.addEventListener("DOMContentLoaded", () => {
      const addBtn = document.getElementById("addCharacterBtn");
      const charInput = document.getElementById("charactersInput");
      const charDisplay = document.getElementById("charactersDisplay");
      const statusEl = document.getElementById("statusMessage");
      const confirmBtn = document.getElementById("confirmButton");

      const characters = [];

      const updateDisplay = () => {
        charDisplay.innerHTML = characters
          .map((c, i) =>
