        const val = charInput.value.trim();
        if (val && !characters.includes(val)) {
          characters.push(val);
          charInput.value = "";
          updateDisplay();
        }
      });

      charInput.addEventListener("keypress", (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          addBtn.click();
        }
      });

      const showStatus = (msg, type) => {
        statusEl.textContent = msg;
        statusEl.style.display = "block";
        statusEl.style.background =
          type === "error"
            ? "linear-gradient(135deg,#ff6b6b 0%,#ee5a52 100%)"
            : "linear-gradient(135deg,#51cf66 0%,#40c057 100%)";
        statusEl.style.color = "#fff";
        setTimeout(() => (statusEl.style.display = "none"), 4000);
      };

      confirmBtn.addEventListener("click", () => {
        const identity = document.getElementById("identityInput").value;
        const locType = document.getElementById("locationTypeInput").value;
        const locDetail = document.getElementById("locationDetailInput").value.trim();
        const plot = document.getElementById("plotInput").value.trim();

        if (!identity || !locType || !plot) {
          showStatus("请填写【身份】【地点类型】【当前剧情】", "error");
          return;
        }

        const location = locDetail ? `${locType} - ${locDetail}` : locType;
        const charList = characters.length ? characters.join("、") : "无其他人物";
        const msg = `身份：${identity}，开场地点：${location}，在场人物：${charList}，当前剧情：${plot}`;

        try {
          if (typeof triggerSlash === "function") {
            triggerSlash(`/send ${msg}|/trigger`);
            showStatus("消息发送成功！", "success");
            return;
          }
          // 回退 postMessage，可按需保留
          window.parent.postMessage({ type: "sillyTavern:send", payload: msg }, "*");
          showStatus("已尝试发送消息", "success");
        } catch (err) {
          console.error(err);
          showStatus("发送失败: " + err.message, "error");
        }
      });
    });
  </script>
